{
  "items": [
    {
      "item_id": "RX-ROPI-02-100",
      "decision": "not_covered",
      "reason": "The recall describes Naropin 0.5% 100 mg/20 mL single-dose vials. RX-ROPI-02-100 is ropivacaine 0.2% 100 mL, a different strength (0.2% vs 0.5%), different volume (100 mL vs 20 mL), and different container (bottle vs single-dose vial). The NDCs differ and the product presentation is not the same."
    },
    {
      "item_id": "RX-ROPI-05-20-SOM",
      "decision": "not_covered",
      "reason": "The recall NDCs (63323-0286-23, 63323-0286-05) are for Fresenius Kabi products. RX-ROPI-05-20-SOM is manufactured by Somerset Therapeutics, LLC and its NDC 70069-0063-25 is not listed in the recall's NDCs. Additionally, the manufacturer differs."
    },
    {
      "item_id": "RX-ROPI-05-20",
      "decision": "covered",
      "reason": "The recall explicitly lists NDC 63323-0286-23 and 63323-0286-05. RX-ROPI-05-20 has NDC 63323-0286-23 and unit_ndcs including 63323-0286-05. This matches the recalled product: Naropin 0.5% 100 mg per 20 mL (5 mg per mL), 25 Single-Dose Vials from Fresenius Kabi. The presentation and strength are identical."
    },
    {
      "item_id": "RX-ROPI-05-30",
      "decision": "covered",
      "reason": "The recall's openFDA family includes NDCs for the 0.5% ropivacaine product line. RX-ROPI-05-30 has NDC 63323-0286-35 and unit_ndcs 63323-0286-11. While the specific unit NDC 63323-0286-11 is not listed verbatim in the recall's ndcs_in_recall_text, it belongs to the same FDA-recognized product family (openfda_family_ndc_count: 41) as the recalled items. The strength (5 mg/mL), manufacturer (Fresenius Kabi), and single-dose vial presentation match the recall description. Decision: covered."
    }
  ]
}

